class ActiveQueue {
  #tail = Promise.resolve();          // serializes method execution
  #items = [];
  put(item) {
    this.#tail = this.#tail.then(() => { this.#items.push(item); });
    return this.#tail.then(() => this.#items.length);   // the future
  }
}
